import GoDFoundation

/// Create a binary patch from the difference between two files.
///
/// Not generated by project setup — hand-authored, like `convert` and the
/// compression ops. Nothing here takes an engine folder: a patch format is
/// fixed knowledge about somebody else's tooling, so the format name is all
/// the operation needs.
enum CreatePatch {

    struct Config: Codable {
        /// The original file — what someone applying the patch will have.
        let sourceFile: File
        /// The modified file — what they should end up with.
        let targetFile: File
        /// Where to write the patch.
        let patchFile: File
        /// Which patch format to write. Named rather than derived: the
        /// output doesn't exist yet, so nothing can say what it should be.
        let format: PatchFormat
        /// Replace an existing `patchFile`. Absent replaces it.
        let overwrite: Bool?

        init(
            sourceFile: File,
            targetFile: File,
            patchFile: File,
            format: PatchFormat,
            overwrite: Bool? = nil
        ) {
            self.sourceFile = sourceFile
            self.targetFile = targetFile
            self.patchFile = patchFile
            self.format = format
            self.overwrite = overwrite
        }
    }
}

/// Apply a binary patch to a file.
enum ApplyPatch {

    struct Config: Codable {
        /// The file to patch.
        let inputFile: File
        /// The patch to apply.
        let patchFile: File
        /// Where to write the result. The same path as `inputFile` is
        /// refused: the patched bytes are verified by reading back what was
        /// written, which the original has to survive for.
        let outputFile: File
        /// Absent reads the format from the patch's magic. A named format
        /// must agree with it.
        let format: PatchFormat?
        /// Absent lets the format decide from its own checksums and sizes,
        /// which is what a caller holding an unknown file wants. Naming
        /// `forward` or `reverse` pins it — a symmetric format like UPS can
        /// un-patch a file with the same patch that patched it.
        let direction: PatchDirection?
        /// Patch a file that isn't what the patch was made from, reporting
        /// every checksum mismatch as a warning instead of refusing. Absent
        /// refuses. This covers the result as well as the input: patching the
        /// wrong file cannot produce the file the patch names, so holding the
        /// output to that checksum would mean this flag could never produce
        /// anything.
        let ignoreChecksums: Bool?
        /// Replace an existing `outputFile`. Absent replaces it.
        let overwrite: Bool?

        init(
            inputFile: File,
            patchFile: File,
            outputFile: File,
            format: PatchFormat? = nil,
            direction: PatchDirection? = nil,
            ignoreChecksums: Bool? = nil,
            overwrite: Bool? = nil
        ) {
            self.inputFile = inputFile
            self.patchFile = patchFile
            self.outputFile = outputFile
            self.format = format
            self.direction = direction
            self.ignoreChecksums = ignoreChecksums
            self.overwrite = overwrite
        }
    }
}
